def manacher(s):
    n = len(s)
    p = [0] * n
    center = right = 0
    for i in range(n):
        mirror = 2 * center - i
        if i < right:
            p[i] = min(right - i, p[mirror])
        while i + 1 + p[i] < n and i - 1 - p[i] >= 0 and s[i + 1 + p[i]] == s[i - 1 - p[i]]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
    return p

